using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTests.LoyaltyDiscount;

public sealed class CalculatePayableTotalAcceptanceTests
{
    [Theory]
    [InlineData(LoyaltyTier.Green, 4_999, 4_750)]    // 249.95 -> floor 249
    [InlineData(LoyaltyTier.Green, 5_000, 4_700)]    // threshold: +1
    [InlineData(LoyaltyTier.Gold, 10_000, 9_200)]
    [InlineData(LoyaltyTier.Platinum, 4_999, 4_549)]  // 449.91 -> floor 449
    [InlineData(LoyaltyTier.Platinum, 5_000, 4_500)]  // 10 points
    [InlineData(LoyaltyTier.Green, 19_999, 18_800)]   // 6 points, 1199.94 floored
    [InlineData(LoyaltyTier.Green, 20_000, 18_400)]   // threshold: +3 = 8
    [InlineData(LoyaltyTier.Gold, 20_000, 18_000)]    // 10
    [InlineData(LoyaltyTier.Platinum, 20_000, 18_000)] // capped at 10
    [InlineData(LoyaltyTier.Gold, 19_999, 18_399)]    // 8 points, 1599.92 floored
    [InlineData(LoyaltyTier.Green, 0, 0)]
    public void CustomersPayTheApprovedLoyaltyTotal(LoyaltyTier tier, int subtotalCents, int expected)
    {
        Assert.Equal(expected, new CalculatePayableTotal().For(subtotalCents, tier));
    }
}
